def clean_html(self, html):
        """Apply ``Cleaner`` to HTML string or document and return a cleaned string or document."""
        if isinstance(html, str):
            html = self.cleaner.clean_html(html)
        elif isinstance(html, bs4.element.Tag):
            html = self.cleaner.clean_element(html)
        else:
            raise TypeError(f"html must be str or bs4.element.Tag, not {type(html)}")
        return html

